        "Andrew N. Cleland",
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum control of mechanical motion makes the quantum-classical boundary experimentally tangible in massive, engineered systems.",
        "attribution": "Cleland, Aspelmeyer, and Kippenberg represent complementary leading experimental routes, though credit is distributed across several communities.",
        "maturity": "Ground-state cooling, measurement, and quantum control have been demonstrated robustly in multiple platforms.",
        "uncertainties": [
          "It remains unclear which single experimental advance best defines the prize-worthy discovery."
        ]
      }
    },
